  "그러나": "/audio/v1/ko-fa207ae3.mp3",
  "그러면 다음 시간에 자료를 함께 보고 결론을 내려요.": "/audio/v1/ko-9ffe867a.mp3",
  "그러면 업무 배분에 따라 다시 확인해 주세요. 저는 예산 승인을 맡을게요.": "/audio/v1/ko-f47a4261.mp3",
