  "내일": "/audio/v1/ko-491c6c59.mp3",
  "내일 가능해요?": "/audio/v1/ko-41a4442e.mp3",
  "내일 만날 거예요.": "/audio/v1/ko-be05e71f.mp3",
  "내일 비가 올 가능성이 있어요.": "/audio/v1/ko-6a579ad3.mp3",
  "내일 시간을 낼 수 있어요?": "/audio/v1/ko-04f103e5.mp3",
  "내일 온다고 했어요.": "/audio/v1/ko-6478dfe3.mp3",
