  "너": "/audio/v1/ko-41e37e86.mp3",
  "너무 화가 나서 참기 어려웠어요.": "/audio/v1/ko-3a0e7db0.mp3",
  "넓": "/audio/v1/ko-58e3a2bb.mp3",
  "넓다": "/audio/v1/ko-6deb95df.mp3",
  "넘어지다": "/audio/v1/ko-b3e8a35b.mp3",
  "네": "/audio/v1/ko-2de35f0a.mp3",
  "네, 가 봤어요. 경치가 정말 좋았어요.": "/audio/v1/ko-c5a301e8.mp3",
  "네, 가끔 친구들이 그리워요. 그래도 새로운 생활에 적응하고 있어요.": "/audio/v1/ko-ba42bcda.mp3",
  "네, 감사합니다.": "/audio/v1/ko-92fd587f.mp3",
  "네, 거실에 텔레비전이 있어요.": "/audio/v1/ko-a533d8b5.mp3",
  "네, 거실이 커요. 거실에 소파가 있어요.": "/audio/v1/ko-e0776f36.mp3",
  "네, 고객 지원 담당자를 채용해요.": "/audio/v1/ko-b3bad59b.mp3",
  "네, 괜찮아요.": "/audio/v1/ko-7fb1eaff.mp3",
  "네, 그리고 환불을 받을 수 있도록 확인해 달라고 했어요.": "/audio/v1/ko-cb21f4ab.mp3",
  "네, 기침이 나고 조금 어지러워요.": "/audio/v1/ko-2a12d9a1.mp3",
  "네, 기침이 있어요.": "/audio/v1/ko-a935fc66.mp3",
  "네, 늦으면 미리 연락할게요.": "/audio/v1/ko-bafeebc8.mp3",
  "네, 다음 주 토요일에는 꼭 갈게요. 시간을 다시 정할까요?": "/audio/v1/ko-a8b98e25.mp3",
  "네, 다음 주에 여행할 거예요.": "/audio/v1/ko-ca02c563.mp3",
  "네, 닭고기 주세요. 그리고 물 주세요.": "/audio/v1/ko-b3671b2c.mp3",
  "네, 답장 보내요.": "/audio/v1/ko-517a64a9.mp3",
  "네, 더블룸이 가능합니다. 조식은 포함되어 있어요.": "/audio/v1/ko-ad5da51e.mp3",
  "네, 동생은 학생이에요.": "/audio/v1/ko-4a14c321.mp3",
  "네, 많이 와요. 그리고 추워요.": "/audio/v1/ko-09b2aaf8.mp3",
  "네, 매워요.": "/audio/v1/ko-e15cd4b3.mp3",
  "네, 며칠 동안 먹어 보면 돼요?": "/audio/v1/ko-cc14a404.mp3",
  "네, 몇 번 해 봤어요. 일본에는 두 번 갔어요.": "/audio/v1/ko-51319e66.mp3",
  "네, 목요일 네 시에 회의실에서 만날까요?": "/audio/v1/ko-ab556ecd.mp3",
  "네, 무슨 일이에요?": "/audio/v1/ko-231ce65d.mp3",
  "네, 문제없어요.": "/audio/v1/ko-02167804.mp3",
  "네, 바다 사진을 많이 찍었어요. 다음에 같이 가요.": "/audio/v1/ko-f0407cdc.mp3",
  "네, 반갑습니다.": "/audio/v1/ko-2c297151.mp3",
  "네, 밤에 쉬어요. 그리고 내일 공부해요.": "/audio/v1/ko-e24fe44b.mp3",
  "네, 보통 어른이 먼저 수저를 드세요. 그런데 가족마다 조금씩 달라요.": "/audio/v1/ko-c3be4703.mp3",
  "네, 비싼 대신에 회사까지 걸어서 다닐 수 있어요.": "/audio/v1/ko-666dfcc0.mp3",
  "네, 산책을 좋아해요.": "/audio/v1/ko-e4242a19.mp3",
  "네, 삼십 분 정도 운동한 후에 출근해요.": "/audio/v1/ko-9751d463.mp3",
  "네, 십 분 지연돼요.": "/audio/v1/ko-bdbc88cd.mp3",
  "네, 아주 재미있었어요. 옛날에 작은 마을이 있었어요.": "/audio/v1/ko-71b1980f.mp3",
  "네, 아주 좋았어요. 그런데 사람이 많아서 조금 피곤했어요.": "/audio/v1/ko-3a405bfc.mp3",
  "네, 알겠습니다. 앞으로는 꼭 미리 연락하겠습니다.": "/audio/v1/ko-c8edc8e9.mp3",
  "네, 어머니는 요리사예요. 그리고 이 사람은 제 동생이에요.": "/audio/v1/ko-cfd649e8.mp3",
  "네, 어제 가 봤어요. 저는 그 공간이 참 좋다고 생각해요.": "/audio/v1/ko-bdf1fe8f.mp3",
  "네, 얼굴은 비슷한데 성격은 완전히 달라요.": "/audio/v1/ko-537afd98.mp3",
  "네, 여기 있어요.": "/audio/v1/ko-693ced5f.mp3",
  "네, 오늘 저녁에 메시지 보낼게요.": "/audio/v1/ko-23af4f72.mp3",
  "네, 옥상 배관이 낡아서 물이 새고 있었어요. 그래서 업체에 빨리 고치도록 요청했어요.": "/audio/v1/ko-74ced320.mp3",
  "네, 은행은 역 근처에 있어요.": "/audio/v1/ko-f2831fbc.mp3",
  "네, 이력서와 자기소개서를 준비해서 지원해 보세요.": "/audio/v1/ko-1306e386.mp3",
  "네, 이어폰을 사용해야 해요.": "/audio/v1/ko-b9ea5d1c.mp3",
  "네, 이천 원이에요.": "/audio/v1/ko-8cf05b40.mp3",
  "네, 이해해요.": "/audio/v1/ko-485573f3.mp3",
  "네, 이해해요. 감사합니다.": "/audio/v1/ko-efcfc304.mp3",
  "네, 일곱 시에 만나요.": "/audio/v1/ko-a5c14340.mp3",
  "네, 일주일에 세 번만 해 보려고요.": "/audio/v1/ko-8baa37db.mp3",
  "네, 있어요.": "/audio/v1/ko-f992e1ea.mp3",
  "네, 재미있었어요.": "/audio/v1/ko-7f7db85f.mp3",
  "네, 저는 수진이라고 합니다. 고객 지원 경험이 있습니다.": "/audio/v1/ko-07d8c9dc.mp3",
  "네, 저는 앞으로도 계속 갈 거라고 생각해요.": "/audio/v1/ko-d4ef3eef.mp3",
  "네, 저는 학생이에요.": "/audio/v1/ko-7daddc44.mp3",
  "네, 저는 회사원이에요. 만나서 반갑습니다.": "/audio/v1/ko-95226899.mp3",
  "네, 제 권한 밖의 일은 혼자 처리하지 않겠습니다.": "/audio/v1/ko-f3c412a5.mp3",
  "네, 조용히 하면 돼요. 그런데 음식은 먹으면 안 돼요.": "/audio/v1/ko-4221a1a5.mp3",
  "네, 좋아요.": "/audio/v1/ko-3ec4d056.mp3",
  "네, 즐거웠어요.": "/audio/v1/ko-ac3d137c.mp3",
  "네, 지난달에 이사하게 되었어요.": "/audio/v1/ko-cbd807ae.mp3",
  "네, 참고 자료도 함께 받았어요. 지난 회의는 의견이 많았던 데 반해, 오늘은 안건이 적어요.": "/audio/v1/ko-9c112320.mp3",
  "네, 토요일이에요.": "/audio/v1/ko-8ed495d0.mp3",
  "네, 파란색이 있어요.": "/audio/v1/ko-ea3e862b.mp3",
  "네, 하루 종일 컴퓨터 앞에 있었어요.": "/audio/v1/ko-62f8b327.mp3",
  "네, 한번 살아 봤어요.": "/audio/v1/ko-2708dcab.mp3",
  "네. 결정 사항은 회의록에 정리하고 모두에게 공유할게요.": "/audio/v1/ko-57793b0e.mp3",
  "네. 경력과 능력을 함께 생각해야 하니까 결정을 미룰 수밖에 없어요.": "/audio/v1/ko-d4a387d4.mp3",
  "네. 고객 문의를 줄이기 위해서 안내문을 새로 만들 거예요.": "/audio/v1/ko-8c61ab41.mp3",
  "네. 그런데 수리를 기다리는 통에 주민들이 계속 불편을 겪고 있어요.": "/audio/v1/ko-0166ad87.mp3",
  "네. 그런데 연구보다 실습 경험이 더 필요해요.": "/audio/v1/ko-2622c865.mp3",
  "네. 길을 잃었지만 현지 사람이 도와줬어요. 그때 친절이 정말 고맙더라고요.": "/audio/v1/ko-f8510e14.mp3",
  "네. 돼지고기는 괜찮아요?": "/audio/v1/ko-013928c9.mp3",
  "네. 보도에 따르면 그 시장이 다음 달에 문을 닫는다고 해요.": "/audio/v1/ko-2ba81dfb.mp3",
  "네. 오래 고민했지만 결국 퇴사하기로 했어요.": "/audio/v1/ko-826d9919.mp3",
  "네. 이번 주 금요일 숙박을 하루 미루고 싶어요.": "/audio/v1/ko-30e5764c.mp3",
  "네. 이용자 수는 작년에 비해 많이 늘었어요.": "/audio/v1/ko-277a645e.mp3",
  "네. 일정이 너무 빡빡해서 아쉬움이 남았어요. 그래도 다음에는 더 천천히 와야겠다는 생각이 들었어요.": "/audio/v1/ko-9c32882d.mp3",
  "네. 재택근무는 시간을 아낄 수 있는 반면에 동료와 대화가 적어요.": "/audio/v1/ko-4d08a931.mp3",
  "네. 저는 결말이 좋았다고 생각해요.": "/audio/v1/ko-048e0e32.mp3",
  "네. 저는 아나예요. 브라질 사람이에요.": "/audio/v1/ko-2954059a.mp3",
  "네. 제가 확인을 늦게 하는 바람에 팀 전체가 다시 작업했어요.": "/audio/v1/ko-6e82c444.mp3",
  "네. 제목은 뭐라고 썼어요?": "/audio/v1/ko-712e3cae.mp3",
  "네. 조심스럽게 걸었지만 사람이 많아서 다시 부딪혔어요.": "/audio/v1/ko-d43f695d.mp3",
  "네. 주스 드세요?": "/audio/v1/ko-f38a28e0.mp3",
  "네. 지난번에는 팀 안에서 업무가 겹쳐서 문제가 생겼어요.": "/audio/v1/ko-7905ad3a.mp3",
  "네. 지연 때문에 예약한 숙소도 취소하고 말았어요.": "/audio/v1/ko-6dc16660.mp3",
  "네. 집주인이 계약을 갑자기 바꿔 버렸어요.": "/audio/v1/ko-89db7d66.mp3",
  "네. 짧게 여러 번 접속하는 경향이 있어요.": "/audio/v1/ko-b53226a9.mp3",
  "네. 처음 보도는 사실과 달랐어요.": "/audio/v1/ko-ab8c0a43.mp3",
  "네? 무슨 메시지예요?": "/audio/v1/ko-d3a774c5.mp3",
